/**
 * This tests the parsers ability to properly ignore the ordering of elements in the Atom feed/entry. The parser
 * should be able to properly select the requested elements regardless of the order in which they appear
 */
@Test
public void testOrder() throws Exception {
    // http://www.snellspace.com/public/ordertest.xml
    IRI uri = new IRI("http://www.snellspace.com/public/ordertest.xml");
    Document<Feed> doc = parse(uri);
    assertNotNull(doc);
    Feed feed = doc.getRoot();
    List<Entry> entries = feed.getEntries();
    int n = 1;
    for (Entry entry : entries) {
        switch(n) {
            case 1:
                assertEquals(new IRI("tag:example.org,2006:atom/conformance/element_order/1"), entry.getIdElement().getValue());
                assertEquals(Text.Type.TEXT, entry.getTitleType());
                assertEquals(Text.Type.TEXT, entry.getSummaryType());
                assertNotNull(entry.getUpdatedElement().getValue());
                assertEquals(1, entry.getLinks(Link.REL_ALTERNATE).size());
                break;
            case 2:
                assertEquals(new IRI("tag:example.org,2006:atom/conformance/element_order/2"), entry.getIdElement().getValue());
                assertEquals(Text.Type.TEXT, entry.getTitleType());
                assertEquals(Text.Type.TEXT, entry.getSummaryType());
                assertNotNull(entry.getUpdatedElement().getValue());
                assertEquals(1, entry.getLinks(Link.REL_ALTERNATE).size());
                break;
            case 3:
                assertEquals(2, entry.getLinks(Link.REL_ALTERNATE).size());
                assertEquals(new IRI("http://www.snellspace.com/public/alternate"), entry.getLinks(Link.REL_ALTERNATE).get(0).getHref());
                assertEquals(new IRI("http://www.snellspace.com/public/alternate2"), entry.getLinks(Link.REL_ALTERNATE).get(1).getHref());
                break;
            case 4:
                assertEquals(1, entry.getLinks(Link.REL_ALTERNATE).size());
                assertEquals(new IRI("http://www.snellspace.com/public/alternate"), entry.getLinks(Link.REL_ALTERNATE).get(0).getHref());
                break;
            case 5:
                Text title = entry.getTitleElement();
                assertEquals(Text.Type.TEXT, entry.getTitleType());
                String value = title.getValue();
                assertEquals("Entry with a source first", value);
                assertEquals(1, entry.getLinks(Link.REL_ALTERNATE).size());
                assertEquals(new IRI("http://www.snellspace.com/public/alternate"), entry.getLinks(Link.REL_ALTERNATE).get(0).getHref());
                break;
            case 6:
                title = entry.getTitleElement();
                assertEquals(Text.Type.TEXT, entry.getTitleType());
                value = title.getValue();
                assertEquals("Entry with a source last", value);
                assertEquals(1, entry.getLinks(Link.REL_ALTERNATE).size());
                assertEquals(new IRI("http://www.snellspace.com/public/alternate"), entry.getLinks(Link.REL_ALTERNATE).get(0).getHref());
                break;
            case 7:
                title = entry.getTitleElement();
                assertEquals(Text.Type.TEXT, entry.getTitleType());
                value = title.getValue();
                assertEquals("Entry with a source in the middle", value);
                assertEquals(1, entry.getLinks(Link.REL_ALTERNATE).size());
                assertEquals(new IRI("http://www.snellspace.com/public/alternate"), entry.getLinks(Link.REL_ALTERNATE).get(0).getHref());
                break;
            case 8:
                title = entry.getTitleElement();
                assertEquals(Text.Type.TEXT, entry.getTitleType());
                value = title.getValue();
                assertEquals("Atom elements in an extension element", value);
                assertEquals(new IRI("tag:example.org,2006:atom/conformance/element_order/8"), entry.getIdElement().getValue());
                break;
            case 9:
                title = entry.getTitleElement();
                assertEquals(Text.Type.TEXT, entry.getTitleType());
                value = title.getValue();
                assertEquals("Atom elements in an extension element", value);
                assertEquals(new IRI("tag:example.org,2006:atom/conformance/element_order/9"), entry.getIdElement().getValue());
                break;
        }
        n++;
    }
}

/**
 * Tests the parsers support for the various link relation types
 */
@Test
public void testLink() throws Exception {
    // http://www.snellspace.com/public/linktests.xml
    IRI uri = new IRI("http://www.snellspace.com/public/linktests.xml");
    Document<Feed> doc = parse(uri);
    assertNotNull(doc);
    Feed feed = doc.getRoot();
    List<Entry> entries = feed.getEntries();
    int n = 1;
    for (Entry entry : entries) {
        switch(n) {
            case 1:
                assertEquals(1, entry.getLinks(Link.REL_ALTERNATE).size());
                assertEquals(new IRI("http://www.snellspace.com/public/linktests/alternate"), entry.getLinks(Link.REL_ALTERNATE).get(0).getHref());
                break;
            case 2:
                assertEquals(4, entry.getLinks(Link.REL_ALTERNATE).size());
                assertEquals(new IRI("http://www.snellspace.com/public/linktests/alternate"), entry.getLinks(Link.REL_ALTERNATE).get(1).getHref());
                assertEquals(new IRI("http://www.snellspace.com/public/linktests/alternate2"), entry.getLinks(Link.REL_ALTERNATE).get(2).getHref());
                break;
            case 3:
                assertEquals(1, entry.getLinks(Link.REL_ALTERNATE).size());
                assertEquals(1, entry.getLinks(Link.REL_ENCLOSURE).size());
                assertEquals(1, entry.getLinks(Link.REL_RELATED).size());
                assertEquals(1, entry.getLinks(Link.REL_SELF).size());
                assertEquals(1, entry.getLinks(Link.REL_VIA).size());
                assertEquals(new IRI("http://www.snellspace.com/public/linktests/alternate"), entry.getLinks(Link.REL_ALTERNATE).get(0).getHref());
                assertEquals(new IRI("http://www.snellspace.com/public/linktests/enclosure"), entry.getLinks(Link.REL_ENCLOSURE).get(0).getHref());
                assertEquals(new IRI("http://www.snellspace.com/public/linktests/related"), entry.getLinks(Link.REL_RELATED).get(0).getHref());
                assertEquals(new IRI("http://www.snellspace.com/public/linktests/self"), entry.getLinks(Link.REL_SELF).get(0).getHref());
                assertEquals(new IRI("http://www.snellspace.com/public/linktests/via"), entry.getLinks(Link.REL_VIA).get(0).getHref());
                break;
            case 4:
                assertEquals(2, entry.getLinks(Link.REL_ALTERNATE).size());
                assertEquals(1, entry.getLinks(Link.REL_ENCLOSURE).size());
                assertEquals(1, entry.getLinks(Link.REL_RELATED).size());
                assertEquals(1, entry.getLinks(Link.REL_SELF).size());
                assertEquals(1, entry.getLinks(Link.REL_VIA).size());
                assertEquals(new IRI("http://www.snellspace.com/public/linktests/alternate"), entry.getLinks(Link.REL_ALTERNATE).get(0).getHref());
                assertEquals(new IRI("http://www.snellspace.com/public/linktests/alternate2"), entry.getLinks(Link.REL_ALTERNATE).get(1).getHref());
                assertEquals(new IRI("http://www.snellspace.com/public/linktests/enclosure"), entry.getLinks(Link.REL_ENCLOSURE).get(0).getHref());
                assertEquals(new IRI("http://www.snellspace.com/public/linktests/related"), entry.getLinks(Link.REL_RELATED).get(0).getHref());
                assertEquals(new IRI("http://www.snellspace.com/public/linktests/self"), entry.getLinks(Link.REL_SELF).get(0).getHref());
                assertEquals(new IRI("http://www.snellspace.com/public/linktests/via"), entry.getLinks(Link.REL_VIA).get(0).getHref());
                break;
            case 5:
                assertEquals(1, entry.getLinks(Link.REL_ALTERNATE).size());
                assertEquals(1, entry.getLinks(Link.REL_LICENSE).size());
                assertEquals(new IRI("http://www.snellspace.com/public/linktests/alternate"), entry.getLinks(Link.REL_ALTERNATE).get(0).getHref());
                assertEquals(new IRI("http://www.snellspace.com/public/linktests/license"), entry.getLinks(Link.REL_LICENSE).get(0).getHref());
                break;
            case 6:
                assertEquals(1, entry.getLinks(Link.REL_ALTERNATE).size());
                assertEquals(1, entry.getLinks("http://example.org").size());
                assertEquals(new IRI("http://www.snellspace.com/public/linktests/alternate"), entry.getLinks(Link.REL_ALTERNATE).get(0).getHref());
                assertEquals(new IRI("http://www.snellspace.com/public/linktests/example"), entry.getLinks("http://example.org").get(0).getHref());
                break;
        }
        n++;
    }
}

/**
 * Test for a concurrency issue that caused a ConcurrentModificationException in Abdera 0.1.0 but seems to be fixed
 * in 0.2. We leave the test here to prevent possible regressions.
 */
@Test
public void testSetContentMT() throws Exception {
    Thread[] t = new Thread[N_THREADS];
    final boolean[] failed = new boolean[t.length];
    for (int i = 0; i < t.length; ++i) {
        final int j = i;
        failed[i] = false;
        Runnable r = new Runnable() {

            public void run() {
                try {
                    setContent();
                } catch (Exception e) {
                    e.printStackTrace();
                    failed[j] = true;
                    fail(e.toString());
                }
            }
        };
        t[i] = new Thread(r);
        t[i].start();
    }
    for (int i = 0; i < t.length; ++i) {
        t[i].join();
        if (failed[i]) {
            fail("Thread " + t[i] + " failed.");
        }
    }
}

/**
 * Link in entry disappears after adding entry to a feed.
 *
 * @see https://issues.apache.org/jira/browse/ABDERA-70 FOM Objects should automatically complete the parse when
 *      modifications are made
 */
@Test
public void testEntryLinkInFeed() throws Exception {
    Abdera abdera = new Abdera();
    Factory factory = abdera.getFactory();
    Feed feed = factory.newFeed();
    feed.setTitle("Test");
    feed.setId("http://example.com/feed");
    Parser parser = abdera.getParser();
    Document<Entry> doc = parser.parse(this.getClass().getResourceAsStream("/entry.xml"));
    Entry entry = doc.getRoot();
    Link link = factory.newLink();
    link.setHref(entry.getId().toString());
    link.setRel(Link.REL_EDIT);
    entry.addLink(link);
    assertNotNull("Link is null", entry.getLink(Link.REL_EDIT));
    feed.addEntry(entry);
    assertNotNull("Link is null", entry.getLink(Link.REL_EDIT));
    for (Entry e : feed.getEntries()) {
        assertNotNull("Link is null", e.getLink(Link.REL_EDIT));
    }
}

